CREATE TABLE customers (id UUID DEFAULT RANDOM_UUID() PRIMARY KEY, lead_id UUID REFERENCES leads(id), booking_id UUID UNIQUE REFERENCES bookings(id), customer_number VARCHAR(40) UNIQUE NOT NULL, full_name VARCHAR(160) NOT NULL, mobile VARCHAR(20) NOT NULL, email VARCHAR(180), status VARCHAR(30) NOT NULL DEFAULT 'ACTIVE', created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE customer_documents (id UUID DEFAULT RANDOM_UUID() PRIMARY KEY, booking_id UUID NOT NULL REFERENCES bookings(id) ON DELETE CASCADE, document_type VARCHAR(60) NOT NULL, file_name VARCHAR(220), storage_key VARCHAR(300), version_no INT NOT NULL DEFAULT 1, verification_status VARCHAR(30) NOT NULL DEFAULT 'PENDING', rejection_reason VARCHAR(500), masked BOOLEAN NOT NULL DEFAULT TRUE, expiry_date DATE, uploaded_by UUID REFERENCES users(id), verified_by UUID REFERENCES users(id), created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE loan_applications (id UUID DEFAULT RANDOM_UUID() PRIMARY KEY, booking_id UUID UNIQUE NOT NULL REFERENCES bookings(id) ON DELETE CASCADE, status VARCHAR(30) NOT NULL DEFAULT 'NOT_APPLIED', bank_name VARCHAR(160), loan_amount DECIMAL(15,2), emi DECIMAL(15,2), sanction_date DATE, loan_officer VARCHAR(160), sanction_document_id UUID REFERENCES customer_documents(id), rejection_reason VARCHAR(500), disbursement_date DATE, updated_by UUID REFERENCES users(id), updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE agreements (id UUID DEFAULT RANDOM_UUID() PRIMARY KEY, booking_id UUID UNIQUE NOT NULL REFERENCES bookings(id) ON DELETE CASCADE, agreement_date DATE, agreement_value DECIMAL(15,2), stamp_duty DECIMAL(15,2), registration_date DATE, registration_number VARCHAR(80), legal_notes VARCHAR(1500), agreement_document_id UUID REFERENCES customer_documents(id), status VARCHAR(30) NOT NULL DEFAULT 'PENDING', updated_by UUID REFERENCES users(id), updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE possession_cases (id UUID DEFAULT RANDOM_UUID() PRIMARY KEY, booking_id UUID UNIQUE NOT NULL REFERENCES bookings(id) ON DELETE CASCADE, status VARCHAR(30) NOT NULL DEFAULT 'NOT_READY', scheduled_date DATE, possession_letter_document_id UUID REFERENCES customer_documents(id), signoff_name VARCHAR(160), signoff_at TIMESTAMP WITH TIME ZONE, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_by UUID REFERENCES users(id), updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE possession_checklist_items (id UUID DEFAULT RANDOM_UUID() PRIMARY KEY, possession_id UUID NOT NULL REFERENCES possession_cases(id) ON DELETE CASCADE, item_code VARCHAR(50) NOT NULL, item_name VARCHAR(160) NOT NULL, completed BOOLEAN NOT NULL DEFAULT FALSE, completed_at TIMESTAMP WITH TIME ZONE, completed_by UUID REFERENCES users(id), remarks VARCHAR(500), UNIQUE(possession_id,item_code));
CREATE INDEX idx_customer_documents_booking ON customer_documents(booking_id,verification_status);
CREATE INDEX idx_possession_items_case ON possession_checklist_items(possession_id,completed);
